import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.CZrxoOIU.js";const u=JSON.parse('{"title":"AI-Assisted Development","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/advanced/ai-agent-skill.md","filePath":"en/guide/advanced/ai-agent-skill.md","lastUpdated":1793431572000}'),i={name:"en/guide/advanced/ai-agent-skill.md"};function l(r,e,o,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="ai-assisted-development" tabindex="-1">AI-Assisted Development <a class="header-anchor" href="#ai-assisted-development" aria-label="Permalink to &quot;AI-Assisted Development&quot;">​</a></h1><p>WebApiClientCore officially maintains an <strong>Agent Skill</strong> (<code>webapiclientcore</code>) for AI coding assistants that support the Agent Skills convention, such as Claude Code and Cursor. It teaches the assistant the correct usage of WebApiClientCore, so generated interface declarations, DI registration, retry, and AOT configurations follow official best practices instead of &quot;guessing&quot; the API from training memory.</p><h2 id="what-the-skill-does" tabindex="-1">What the Skill Does <a class="header-anchor" href="#what-the-skill-does" aria-label="Permalink to &quot;What the Skill Does&quot;">​</a></h2><p>Once installed, when your conversation touches on declarative HTTP clients, <code>WebApiClientCore</code>, <code>AddHttpApi</code>, <code>ITask</code> retries, OAuth token management, and similar topics, the AI automatically loads the skill and gains access to:</p><ul><li><strong>Decision tree</strong>: when to use WebApiClientCore and when a plain HttpClient is enough</li><li><strong>Interface declaration templates</strong>: correct combinations of HttpHost / HttpGet / JsonContent attributes</li><li><strong>Common code patterns</strong>: ITask conditional retry, default-value-on-exception, file upload, filters, OAuth2 Client Credentials, AOT publishing, JSON-RPC</li><li><strong>Attribute cheat sheets</strong>: request body formats (Json/Xml/Form/FormData/RawString), response parsing, authentication and headers</li><li><strong>Exception handling reference</strong>: concrete exception types wrapped by <code>HttpRequestException</code> and handling advice</li><li><strong>A full reference manual</strong> (<code>reference.md</code>, ~1000 lines): custom serialization, dynamic HttpHost, data validation, cookie refresh, adapting unusual APIs, and more</li></ul><h2 id="getting-and-installing" tabindex="-1">Getting and Installing <a class="header-anchor" href="#getting-and-installing" aria-label="Permalink to &quot;Getting and Installing&quot;">​</a></h2><p>The skill lives in the <a href="https://github.com/dotnetcore/WebApiClient/tree/master/skills/webapiclientcore" target="_blank" rel="noreferrer"><code>skills/webapiclientcore</code></a> directory of the <a href="https://github.com/dotnetcore/WebApiClient" target="_blank" rel="noreferrer">WebApiClient repository</a> and contains two files:</p><table tabindex="0"><thead><tr><th>File</th><th>Description</th></tr></thead><tbody><tr><td><code>SKILL.md</code></td><td>Agent instructions: triggers, decision tree, templates and patterns</td></tr><tr><td><code>reference.md</code></td><td>Full reference manual</td></tr></tbody></table><p>Copy the entire <code>webapiclientcore</code> directory into your AI tool&#39;s project skill directory:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Skill directory</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>.claude/skills/webapiclientcore/</code></td></tr><tr><td>Cursor</td><td><code>.cursor/skills/webapiclientcore/</code></td></tr><tr><td>Other tools supporting the Agent Skills convention</td><td>Place the <code>SKILL.md</code> directory as documented</td></tr></tbody></table><p>For example, with Claude Code, run in your project root:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dotnetcore/WebApiClient.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp-wac</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/skills</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp-wac/skills/webapiclientcore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/skills/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp-wac</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>You can also download just the two files into the directory above:</p><ul><li><a href="https://github.com/dotnetcore/WebApiClient/raw/master/skills/webapiclientcore/SKILL.md" target="_blank" rel="noreferrer">SKILL.md</a></li><li><a href="https://github.com/dotnetcore/WebApiClient/raw/master/skills/webapiclientcore/reference.md" target="_blank" rel="noreferrer">reference.md</a></li></ul><h2 id="usage-example" tabindex="-1">Usage Example <a class="header-anchor" href="#usage-example" aria-label="Permalink to &quot;Usage Example&quot;">​</a></h2><p>No extra steps are needed after installation — just chat with your AI as usual:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; Help me call the user API of https://api.example.com with retry on failure</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(The AI loads the webapiclientcore skill automatically and generates</span></span>
<span class="line"><span> code that follows official practice)</span></span>
<span class="line"><span>[LoggingFilter]</span></span>
<span class="line"><span>[HttpHost(&quot;https://api.example.com/&quot;)]</span></span>
<span class="line"><span>public interface IUserApi</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [HttpGet(&quot;api/users/{id}&quot;)]</span></span>
<span class="line"><span>    ITask&lt;User&gt; GetUserAsync(string id, CancellationToken token = default);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Usage: exponential backoff, retry only on network exceptions</span></span>
<span class="line"><span>var user = await api.GetUserAsync(id)</span></span>
<span class="line"><span>    .Retry(3, i =&gt; TimeSpan.FromSeconds(Math.Pow(2, i)))</span></span>
<span class="line"><span>    .WhenCatch&lt;HttpRequestException&gt;();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><ul><li>The skill evolves with the main repository; API changes (such as the ITokenProvider cancellation token support in <code>v2.1.6</code>) are reflected in both the skill and this documentation.</li><li>If the AI generates code that does not follow best practices, feel free to open an issue in the <a href="https://github.com/dotnetcore/WebApiClient/issues" target="_blank" rel="noreferrer">WebApiClient repository</a>.</li></ul>`,19)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
